const paths={phone:'M7 3H4a1 1 0 0 0-1 1c0 9.4 7.6 17 17 17a1 1 0 0 0 1-1v-3l-5-2-2 2a15 15 0 0 1-7-7l2-2-2-5Z',end:'M3 15v-3c5-5 13-5 18 0v3h-5v-3a13 13 0 0 0-8 0v3H3Z',mic:'M9 4a3 3 0 0 1 6 0v8a3 3 0 0 1-6 0V4ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8',back:'m14 5-7 7 7 7',down:'m5 9 7 7 7-7',close:'m6 6 12 12M6 18 18 6',alert:'M12 8v5M12 17h.01M10 3 2 19h20L14 3h-4'};
const icon=(name)=>`<svg viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.phone}"/></svg>`;
let lang='zh',scenario='dial',state='idle',left=240,peer=200,elapsed=0,limit=200,muted=false,minimized=false,records=[],modal='',ring=0,recovering=0,toastTimer;
const $=id=>document.getElementById(id), t=key=>copy[lang][key]||key, time=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;
const active=()=>['ringing','incoming','connecting','active','reconnecting'].includes(state);
const action=(name,label,style='',glyph='phone')=>`<button class="action ${style}" data-action="${name}"><i>${icon(glyph)}</i>${t(label)}</button>`;
function toast(message){$('toast').textContent=message;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4200)}
function choose(next){scenario=next;state='idle';left=next==='selfEmpty'?0:240;peer=next==='peerEmpty'?0:200;elapsed=0;muted=false;minimized=false;records=[];modal='';if(next==='incoming'){begin(true);toast(t('mockNotification'))}else if(next==='low'){left=15;peer=200;begin(false);connect()}else if(next!=='dial')modal='confirm';render()}
function blocked(){return scenario==='selfEmpty'?'emptyMine':scenario==='peerEmpty'?'emptyPeer':scenario==='notVip'?'vip':scenario==='busy'?'busy':scenario==='permission'?'permission':left<=0?'emptyMine':peer<=0?'emptyPeer':''}
function begin(incoming=false){if(active())return;limit=Math.min(left,peer);elapsed=0;ring=30;state=incoming?'incoming':'ringing';modal='call';minimized=false;records.push({incoming,status:'bubbleRing',duration:0,charged:false});render()}
function connect(){state='active';modal='call';records.at(-1).status='bubbleActive';render()}
function end(reason){if(!active())return;const charged=elapsed>0;left=Math.max(0,left-elapsed);peer=Math.max(0,peer-elapsed);Object.assign(records.at(-1),{status:reason,duration:elapsed,charged});state='ended';modal='';minimized=false;render();if(charged)toast(t(reason==='exhausted'?'quotaEnd':'endedToast'))}
function render(){document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.querySelectorAll('[data-i]').forEach(el=>el.textContent=t(el.dataset.i));document.querySelectorAll('[data-label]').forEach(el=>el.setAttribute('aria-label',t(el.dataset.label)));document.querySelector('[data-action="back"]').innerHTML=icon('back');document.querySelector('.phone-entry').innerHTML=icon('phone');$('language').textContent=lang==='zh'?'English':'中文';$('scenarios').innerHTML=['dial','incoming','selfEmpty','peerEmpty','notVip','busy','permission','low'].map(s=>`<button data-scenario="${s}" class="${scenario===s?'active':''}" aria-pressed="${scenario===s}">${t(s)}</button>`).join('');
const category=blocked()?'failed':state==='incoming'?'in':state==='ringing'?'out':['active','reconnecting'].includes(state)?'active':state==='ended'?'ended':'idle';$('state-title').textContent=t(category+'Title');$('state-description').textContent=t(category+'Description');const balance=Math.max(0,left-(['active','reconnecting'].includes(state)?elapsed:0));$('quota-number').textContent=time(balance)+' / 05:00';$('quota-fill').style.width=balance/300*100+'%';
$('records').innerHTML=records.map((r,i)=>`<button class="bubble ${r.incoming?'incoming':''}" data-record="${i}">${icon('phone')}<span><strong>${t(r.status)}${r.duration?' · '+time(r.duration):''}</strong><small>${t(r.charged?'charged':['bubbleRing','bubbleActive'].includes(r.status)?'voice':'noCharge')}</small></span></button>`).join('');
$('compact').hidden=!(minimized&&active());$('compact').innerHTML=icon('phone')+`<span>${t(state==='ringing'?'waiting':state==='incoming'?'invite':state==='reconnecting'?'reconnecting':'connected')} ${['active','reconnecting'].includes(state)?time(elapsed):''}</span>↗`;
let html='';const top=(label,close='close')=>`<div class="handle"></div><div class="sheet-top"><span>${t(label)}</span><button class="icon-button sheet-close" data-action="${close}" aria-label="${t(close==='minimize'?'minimize':'close')}">${icon(close==='minimize'?'down':'close')}</button></div>`;
if(modal==='confirm'){const reason=blocked();html=top('voice')+(reason?`<div class="alert-symbol">${icon('alert')}</div><h2>${t(reason+'Title')}</h2><p>${t(reason+'Body')}</p><button class="primary" data-action="close">${t('close')}</button>`:`<h2>${t('startTitle')}</h2><p>${t('startBody')}</p><div class="inline-notice">${t('max')} <strong>${time(Math.min(left,peer))}</strong></div><button class="primary" data-action="start">${icon('phone').replace('<svg','<svg style="display:inline-block;width:16px;height:16px;vertical-align:middle;margin-right:7px"')} ${t('start')}</button><button class="secondary" data-action="close">${t('cancel')}</button>`)}
else if(modal==='quota'){html=top('details')+`<h2>${t('quotaTitle')}</h2><p>${t('quotaBody')}</p><div class="quota-row"><span>${t('mine')}</span><strong>${time(balance)}</strong></div><div class="quota-row"><span>${t('total')}</span><strong>05:00</strong></div><div class="quota-row"><span>${t('refresh')}</span><strong>${t('monday')}</strong></div><p>${t('reset')}</p><button class="primary" data-action="close">${t('close')}</button>`}
else if(modal==='call'&&active()){const speaking=['active','reconnecting'].includes(state);html=top('voice','minimize')+`<div class="call-center"><div class="large-avatar">林</div><h2 class="call-name">${t('person')}</h2><p class="call-status">${t(state==='incoming'?'invite':state==='ringing'?'waiting':state==='reconnecting'?'reconnecting':'connected')}</p>${speaking?`<div class="timer">${time(elapsed)}</div>`:''}<div class="remaining ${speaking&&limit-elapsed<=15?'warning':''}">${t(speaking?'remaining':'max')} ${time(speaking?limit-elapsed:limit)}</div>${state==='reconnecting'?`<p class="footnote">${t('reconnectNote')}</p>`:speaking&&limit-elapsed<=15?`<p class="footnote warning">${t('lowWarning')}</p>`:''}<div class="call-actions">${state==='incoming'?action('decline','decline','danger','end')+action('accept','accept','accept'):speaking?action('mute',muted?'unmute':'mute',muted?'muted':'','mic')+action('hangup','hangup','danger','end'):action('hangup','cancelCall','danger','end')}</div><p class="footnote">${t('foreground')}</p></div>${state==='ringing'?`<div class="inline-notice">${t('simulated')}<button class="secondary" data-action="accept">${t('simulateAnswer')}</button><button class="secondary" data-action="decline">${t('simulateReject')}</button><button class="secondary" data-action="timeout">${t('simulateTimeout')}</button></div>`:speaking?`<button class="secondary" data-action="${state==='reconnecting'?'recover':'reconnect'}">${t(state==='reconnecting'?'recover':'reconnect')}</button>`:''}`}
$('surface').hidden=!html;$('surface').innerHTML=html?`<section class="sheet" role="dialog" aria-modal="true" aria-label="${t('voice')}" tabindex="-1">${html}</section>`:'';
}
document.addEventListener('click',e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.scenario){choose(button.dataset.scenario);return}if(button.id==='theme'){document.documentElement.classList.toggle('dark');return}if(button.id==='language'){lang=lang==='zh'?'en':'zh';render();return}if(button.dataset.record!==undefined){if(active()&&Number(button.dataset.record)===records.length-1){modal='call';minimized=false}else modal='confirm';render();return}switch(button.dataset.action){case'dial':if(active()){modal='call';minimized=false}else modal='confirm';break;case'start':if(!blocked())begin();return;case'accept':if(['ringing','incoming'].includes(state))connect();return;case'decline':end('rejected');return;case'timeout':end('missed');return;case'hangup':end(['active','reconnecting'].includes(state)?'completed':'cancelled');return;case'close':modal='';break;case'quota':modal='quota';break;case'minimize':minimized=true;modal='';break;case'expand':minimized=false;modal='call';break;case'mute':muted=!muted;break;case'back':modal='';if(active())minimized=true;break;case'reconnect':state='reconnecting';recovering=10;break;case'recover':state='active';break}render();if(modal)$('surface').querySelector('.sheet')?.focus()});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal){if(active())minimized=true;modal='';render();document.querySelector('.phone-entry').focus()}if(e.key==='Tab'&&modal){const items=[...$('surface').querySelectorAll('button:not(:disabled)')];const first=items[0],last=items.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===$('surface').firstChild)){e.preventDefault();last.focus()}else if(!e.shiftKey&&(document.activeElement===last||!$('surface').contains(document.activeElement))){e.preventDefault();first.focus()}}});
setInterval(()=>{if(['active','reconnecting'].includes(state)){elapsed++;if(elapsed>=limit){end('exhausted');return}if(state==='reconnecting'&&--recovering<=0){end('networkEnd');return}const focused=document.activeElement;const actionName=focused?.dataset?.action;const focusedId=focused?.id;const focusedScenario=focused?.dataset?.scenario;render();if(actionName)document.querySelector(`[data-action="${actionName}"]`)?.focus({preventScroll:true});else if(focusedId)$(focusedId)?.focus({preventScroll:true});else if(focusedScenario)document.querySelector(`[data-scenario="${focusedScenario}"]`)?.focus({preventScroll:true})}else if(['ringing','incoming'].includes(state)&&--ring<=0)end('missed')},1000);
render();
